#include <memory>
#include <iostream>

int main() {
    std::unique_ptr<int> ptr1(new int(10));  // Allocates and manages an int
    std::unique_ptr<int> ptr2(new int(20));  // Another managed int
    if (ptr1 > ptr2) {  // Compares the raw pointers: ptr1.get() > ptr2.get()
        std::cout << "ptr1's pointer is greater than ptr2's" << std::endl;
    } else {
        std::cout << "ptr1's pointer is not greater than ptr2's" << std::endl;
    }
    return 0;
}
